insert into companies (slug, name, contact_first_name, greeting_name, intro_basis, email_known, direction_shape, offer_text, unlock_mode, show_scarcity, is_internal)
values ('gravitysketch-nl01j2', 'Gravity Sketch', 'Oluwaseyi', 'Oluwaseyi', 'your Donkervoort, Ford and DLR stories, and the questions design leads ask before they move reviews into VR', true, to_jsonb('1 long-form article + 2 short insights'::text), null, 'call', false, false)
