insert into cards (company_id, card_key, format, title, angle, evidence, tags, sources, sort_order)
select id, 'r2-04', 'long_form', 'VR Mesh to Class A: The Conversion Step', 'Car programs are compressing toward two-year cycles, and the slowest handoff in exterior design is still getting a concept surface into a Class A tool. The problem is not that VR cannot export NURBS; it is that polygon data converted to NURBS patches is hard to edit afterward.', 'Your Donkervoort F22 story shows a Gravity Sketch mesh going straight to CNC milling at quality matching scanned clay, and your own export guide warns about editing converted patches. No article on your site walks a surfacing lead through when to convert, when to rebuild and when to mill from mesh.', '{class-a-surfacing,long-form,customer-story}'::text[], '[{"title": "Designing the Donkervoort F22", "publisher": "Gravity Sketch", "url": "https://gravitysketch.com/resources/type/customer-stories/designing-the-donkervoort-f22/"}, {"title": "Export Best Practices", "publisher": "Gravity Sketch Help", "url": "https://help.gravitysketch.com/hc/en-us/articles/5902439321629-Export-Best-Practices"}, {"title": "Chinese Brands Got So Fast At Developing New Cars", "publisher": "Carscoops", "url": "https://www.carscoops.com/2026/09/chinese-automakers-should-slow-down-development/"}]'::jsonb, 0 from companies where slug = 'gravitysketch-nl01j2'
on conflict (company_id, card_key) do update set format = excluded.format, title = excluded.title, angle = excluded.angle, evidence = excluded.evidence, tags = excluded.tags, sources = excluded.sources, sort_order = excluded.sort_order;
insert into cards (company_id, card_key, format, title, angle, evidence, tags, sources, sort_order)
select id, 'r2-05', 'short_insight', 'Milling Budgets Under 24-Month Car Programs', 'Renault shipped Twingo E-Tech in 21 months and Chinese OEMs run two-year cycles. Each physical milling pass is a line item that program timing no longer tolerates.', 'Donkervoort''s public figure is up to 40,000 EUR per milling pass, reduced to one verification mill after 1:1 VR sign-off; Ford''s Paul Wraith describes catching errors before milling. The piece is where clay still earns its cost and why.', '{automotive-design,short-insight,customer-story}'::text[], '[{"title": "Designing the Donkervoort F22", "publisher": "Gravity Sketch", "url": "https://gravitysketch.com/resources/type/customer-stories/designing-the-donkervoort-f22/"}, {"title": "Paul Wraith on Gravity Sketch at Ford Design", "publisher": "Gravity Sketch", "url": "https://gravitysketch.com/resources/type/customer-stories/paul-wraith-on-the-integration-of-gravity-sketch-into-ford-designs-process/"}, {"title": "Chinese Brands Got So Fast At Developing New Cars", "publisher": "Carscoops", "url": "https://www.carscoops.com/2026/09/chinese-automakers-should-slow-down-development/"}]'::jsonb, 1 from companies where slug = 'gravitysketch-nl01j2'
on conflict (company_id, card_key) do update set format = excluded.format, title = excluded.title, angle = excluded.angle, evidence = excluded.evidence, tags = excluded.tags, sources = excluded.sources, sort_order = excluded.sort_order;
insert into cards (company_id, card_key, format, title, angle, evidence, tags, sources, sort_order)
select id, 'r2-06', 'short_insight', 'Two-Hour VR Sessions for Non-Designers', 'Stakeholder reviews are moving into headsets, and the people in them are passengers, crew and executives, not designers. Your only comfort guidance dates from 2021 and caps continuous use at an hour.', 'DLR ran 18 two-hour sessions with 65 passengers who had no XR experience to validate cabin concepts at 1:1 scale, with a short grab-duplicate-undo intro. What hardware, session design and fallback made that work is undocumented on your site.', '{vr-usability,short-insight,customer-story}'::text[], '[{"title": "DLR cabin concept validation at 1:1 scale", "publisher": "Gravity Sketch", "url": "https://gravitysketch.com/resources/type/customer-stories/user-testing-in-vr-dlrs-approach-to-cabin-concept-validation-at-11-scale/"}, {"title": "Everything you need to know to work in VR comfortably", "publisher": "Gravity Sketch", "url": "https://gravitysketch.com/blog-post/articles/everything-you-need-to-know-to-work-in-vr-comfortably/"}, {"title": "Gravity Sketch 6.7 (Quest alignment support)", "publisher": "Gravity Sketch", "url": "https://gravitysketch.com/blog-post/updates/gravity-sketch-6-7/"}]'::jsonb, 2 from companies where slug = 'gravitysketch-nl01j2'
